const{spawnSync}=require("child_process");const fs=require("fs");
const args=process.argv.slice(2);
for(const f of args){
  let a;
  if(f.startsWith("STR:")) a=f.slice(4);
  else a=fs.readFileSync(f,"utf8");
  const r=spawnSync("/workspace/dataset/test9_executable",["--a",a],{encoding:"utf8"});
  process.stdout.write("=== "+JSON.stringify(a)+"\nRC="+r.status+"\n");
  if(r.status===0){
    // show with visible markers
    process.stdout.write(r.stdout.replace(/\t/g,"<TAB>").replace(/ /g,"·").replace(/\n/g,"<NL>\n"));
  } else {
    const el=r.stderr.trim().split("\n");
    process.stdout.write("STDERR_TAIL:\n"+el.slice(-8).join("\n")+"\n");
  }
  process.stdout.write("---end---\n");
}
EOF
