const mark = process.argv[3]==="raw";
for(const a of vals){
  const r=spawnSync("/workspace/dataset/test9_executable",["--a",a],{encoding:"utf8"});
  process.stdout.write("IN "+JSON.stringify(a)+"\n");
  if(r.status===0){
    let o=r.stdout;
    if(!mark) o=o.replace(/ /g,"·").replace(/\t/g,"<TAB>").replace(/\n/g,"<NL>\n");
    process.stdout.write("OK "+JSON.stringify(r.stdout)+"\n");
  } else {
    const el=r.stderr.trim().split("\n").filter(l=>l.trim().length);
    process.stdout.write("ERR "+JSON.stringify(el.slice(-4).join(" | "))+"\n");
  }
}
EOF
